package com.crm.invoice.entity;import jakarta.persistence.*;import lombok.Data;import java.time.*;
@Entity @Table(name="invoice_reminder_tasks",uniqueConstraints=@UniqueConstraint(columnNames={"invoice_id","policy_revision","scheduled_for"})) @Data public class ReminderTask {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="invoice_id",nullable=false,updatable=false) private Long invoiceId;@Column(name="policy_revision",nullable=false,updatable=false) private long policyRevision;@Column(name="scheduled_for",nullable=false,updatable=false) private LocalDate scheduledFor;@Column(nullable=false,length=30,updatable=false) private String channel;@Column(nullable=false,length=500,updatable=false) private String message;@Column(nullable=false,length=20) private String state="PREPARED";@Column(length=500) private String outcome;@Column(name="handled_by") private Long handledBy;@Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt;@PrePersist void created(){createdAt=LocalDateTime.now();}}
